      if(collectionLanguage!=='all'){
        const lang=String(g.language||'en').toLowerCase();
        const matches=collectionLanguage==='ja'?lang==='ja':collectionLanguage==='zh-cn'?lang==='zh-cn':collectionLanguage==='zh-tw'?lang==='zh-tw':!['ja','zh-cn','zh-tw'].includes(lang);
        if(!matches)return {...g,cards:[],ownedUnique:0,missing:0};
      }
      const query=collectionQuery.trim().toLowerCase();
      const setMatches=query&&g.setName.toLowerCase().includes(query);
      const visible=g.cards.filter(c=>{
        const ownedEntries=collection.filter(x=>x.id===c.id||x.id.startsWith(c.id+'::'));
        const isOwned=ownedEntries.length>0;
        const quantity=ownedEntries.reduce((n,x)=>n+x.quantity,0);
        if(collectionOwnershipFilter==='owned'&&!isOwned)return false;
        if(collectionOwnershipFilter==='missing'&&isOwned)return false;
        if(collectionOwnershipFilter==='duplicates'&&quantity<2)return false;
        if(collectionRarities.length&&!collectionRarities.includes(String(c.rarity||'__none__')))return false;
        if(collectionTypes.length&&!collectionTypes.some(t=>(c.types||[]).includes(t)))return false;
        if(collectionVariants.length&&!collectionVariants.includes(String(c.variantLabel||'Standard')))return false;
        if(collectionConditions.length&&!ownedEntries.some(x=>collectionConditions.includes(x.condition)))return false;
        if(collectionLanguages.length&&!collectionLanguages.includes(String(c.language||'en')))return false;
        if(!query)return true;
        return setMatches||String(c.name||'').toLowerCase().includes(query)||String(c.number||'').toLowerCase().includes(query)||String(c.setName||g.setName).toLowerCase().includes(query);
      });
      const sorted=[...visible].sort((a,b)=>{
        const ownedA=collection.find(x=>x.id===a.id),ownedB=collection.find(x=>x.id===b.id);
        if(collectionSort==='priceAsc')return (a.priceEUR??Number.POSITIVE_INFINITY)-(b.priceEUR??Number.POSITIVE_INFINITY);
        if(collectionSort==='priceDesc')return (b.priceEUR??0)-(a.priceEUR??0);
        if(collectionSort==='conditionAsc')return conditionRank(ownedA?.condition)-conditionRank(ownedB?.condition);
        if(collectionSort==='conditionDesc')return conditionRank(ownedB?.condition)-conditionRank(ownedA?.condition);
        if(collectionSort==='nameAsc')return a.name.localeCompare(b.name,'it',{sensitivity:'base'});
        if(collectionSort==='nameDesc')return b.name.localeCompare(a.name,'it',{sensitivity:'base'});
        if(collectionSort==='artistAsc')return String(a.artist||'').localeCompare(String(b.artist||''),'it',{sensitivity:'base'});
        if(collectionSort==='artistDesc')return String(b.artist||'').localeCompare(String(a.artist||''),'it',{sensitivity:'base'});
        if(collectionSort==='dateAsc')return String(a.releaseDate||'9999-99-99').localeCompare(String(b.releaseDate||'9999-99-99'));
        if(collectionSort==='dateDesc')return String(b.releaseDate||'0000-00-00').localeCompare(String(a.releaseDate||'0000-00-00'));
        if(collectionSort==='dexAsc')return (Number(a.dexId)||999999)-(Number(b.dexId)||999999);
        if(collectionSort==='dexDesc')return (Number(b.dexId)||0)-(Number(a.dexId)||0);
        const na=String(a.number||'').match(/\d+/)?.[0],nb=String(b.number||'').match(/\d+/)?.[0];
        const nc=(na?Number(na):999999)-(nb?Number(nb):999999);
        return collectionSort==='numberAsc'?(nc||String(a.number||'').localeCompare(String(b.number||''))):(-nc||String(b.number||'').localeCompare(String(a.number||'')));
      });
